window.docContents[153].resolve({"/Terms/#Cvc___lean----High-Level-CVC5-API--Terms--Typed-Terms--Examples":{"contents":"Examples of using term constructors follow, feel free to hover around to make sure the terms are\ncorrectly typed.\n\nopen Typed in #eval Env.runIO do\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let b2 ← Term.mkSymbol \"b2\"\n  let conj ← b1.and b2\n  println! \"conj := {conj}\"\n  let i1 ← Term.mkSymbol \"i1\"\n  let zero ← Term.mkInt 0\n  let i1_pos ← zero.le i1\n  println! \"i1_pos := {i1_pos}\"\n  let i2 ← Term.mkSymbol \"i2\"\n  let ite ← i1_pos.ite i1 i2\n  println! \"ite := {ite}\"\n\n\nconj := (and b1 b2)\ni1_pos := (<= 0 i1)\nite := (ite (<= 0 i1) i1 i2)\n\n\nInterestingly, strong-typing works with functions as well.\n\nopen Typed in #eval Env.runIO do\n  let f ← Term.mkSymbolAs (Int → Bool → Int) \"f\"\n  println! \"f : {← f.getSort} := {f}\"\n  let i ← Term.mkSymbol \"i\"\n  let f_i ← f.apply i\n  println! \"f_i : {← f_i.getSort} := {f_i}\"\n  let b ← Term.mkSymbol \"b\"\n  let f_i_b ← f_i.apply b\n  println! \"f_i_b : {← f_i_b.getSort} := {f_i_b}\"\n  -- alternatively\n  let f_i_b' ← f.apply2 i b\n  println! \"f_i_b' : {← f_i_b'.getSort} := {f_i_b'}\"\n\n\nf : (-> Int Bool Int) := f\nf_i : (-> Bool Int) := (f i)\nf_i_b : Int := (f i b)\nf_i_b' : Int := (f i b)\n\n\nOf course, type-checking catches any invalid-sort mistake we make.\n\nopen Typed in #eval Env.runIO do\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let b2 ← Term.mkSymbolAs Int \"b2\"\n  let conj ← b1.and b2\n  println! \"conj := {conj}\"\n\n\nAnother type-checking error on function application:\n\nopen Typed in #eval Env.runIO do\n  let f ← Term.mkSymbolAs (Bool → String → Rat) \"f\"\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let f_b1_i1 ← f.apply2 b1 i1\n  println! \"f_b1_i1 := {f_b1_i1}\"\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Terms\u0009Typed Terms","header":"3.1.1. Examples","id":"/Terms/#Cvc___lean----High-Level-CVC5-API--Terms--Typed-Terms--Examples"}});